+/**
+ * Sanitize SVG content to prevent XSS attacks.
+ * Removes dangerous elements and attributes from SVG documents.
+ */
+
+/**
+ * List of elements that should be removed from SVGs to prevent XSS.
+ * @type {Array<string>}
+ */
+const DANGEROUS_ELEMENTS = [
+    'script',
+    'animate',
+    'set',
+    'animateMotion',
+    'animateTransform',
+    'animateColor',
+    'handler',
+    'listener',
+    'prefetch',
+    'discard'
+];
+
+/**
+ * List of attribute prefixes/names that could execute scripts.
+ * @type {Array<string>}
+ */
+const DANGEROUS_ATTRIBUTES = [
+    'onload',
+    'onclick',
+    'onmouseover',
+    'onmouseout',
+    'onmousemove',
+    'onfocus',
+    'onblur',
+    'onerror',
+    'onabort',
+    'onactivate',
+    'onbegin',
+    'onend',
+    'onrepeat',
+    'onresize',
+    'onscroll',
+    'onunload',
+    'onzoom',
+    'href',
+    'xlink:href'
+];
+
+/**
+ * Remove dangerous elements and attributes from an SVG DOM tree.
+ * @param {SVGElement} svgElement - The root SVG element to sanitize.
+ * @returns {SVGElement} The sanitized SVG element.
+ */
+const sanitizeSvgElement = function (svgElement) {
+    // Remove dangerous child elements
+    DANGEROUS_ELEMENTS.forEach(tagName => {
+        const elements = svgElement.querySelectorAll(tagName);
+        elements.forEach(el => el.parentNode && el.parentNode.removeChild(el));
+    });
+
+    // Remove dangerous attributes from all elements
+    const allElements = svgElement.querySelectorAll('*');
+    allElements.forEach(el => {
+        DANGEROUS_ATTRIBUTES.forEach(attr => {
+            if (el.hasAttribute(attr)) {
+                // Allow safe href/xlink:href (non-javascript)
+                if (attr === 'href' || attr === 'xlink:href') {
+                    const val = el.getAttribute(attr) || '';
+                    if (/^\s*javascript:/i.test(val)) {
+                        el.removeAttribute(attr);
+                    }
+                } else {
+                    el.removeAttribute(attr);
+                }
+            }
+        });
+        // Also check the element itself (root svg)
+    });
+
+    // Check root element attributes too
+    DANGEROUS_ATTRIBUTES.forEach(attr => {
+        if (svgElement.hasAttribute && svgElement.hasAttribute(attr)) {
+            if (attr === 'href' || attr === 'xlink:href') {
+                const val = svgElement.getAttribute(attr) || '';
+                if (/^\s*javascript:/i.test(val)) {
+                    svgElement.removeAttribute(attr);
+                }
+            } else {
+                svgElement.removeAttribute(attr);
+            }
+        }
+    });
+
+    return svgElement;
+};
+
+module.exports = sanitizeSvgElement;
